'use strict';
// Fictional fixtures only. This prototype never fetches teaching data.
const COURSES=[{id:'math',name:'高等数学（上）',students:48,term:'2026',warn:6},{id:'ai',name:'人工智能安全',students:36,term:'2026',warn:3},{id:'empty',name:'新建课程',students:0,term:'2026',warn:0}];
const SESSIONS=Array.from({length:16},(_,i)=>{const c=COURSES[i%2],total=c.students,present=total-(i%4+1),answered=present-(i%3);return {courseId:c.id,date:`2026-10-${String(1+i*2).padStart(2,'0')}`,total,present,answered,correct:Math.round(answered*(.62+(i%5)*.06)),late:i%3};});
const HOMEWORK=[{courseId:'math',name:'极限与连续 · 第三次作业',date:'2026-10-28',total:48,scored:38,missing:3,matched:42,pending:2,abnormal:1,mean:81},{courseId:'ai',name:'生成对抗网络 · 案例练习',date:'2026-10-26',total:36,scored:27,missing:2,matched:31,pending:1,abnormal:2,mean:85},{courseId:'math',name:'导数计算 · 第二次作业',date:'2026-10-18',total:48,scored:45,missing:2,matched:46,pending:0,abnormal:0,mean:78}];
const SURVEYS=[{courseId:'math',name:'阶段学习情况反馈',date:'2026-10-29',mode:'named',target:48,count:41,status:'回收中'},{courseId:'ai',name:'课堂体验与课程建议',date:'2026-10-27',mode:'anonymous',target:0,count:28,status:'回收中'},{courseId:'ai',name:'人工智能安全 · 课前了解',date:'2026-10-15',mode:'named',target:36,count:34,status:'已结束'}];
const RESOURCES=[{courseId:'ai',name:'深度伪造原理与安全应用',type:'PPT',date:'2026-10-29',status:'待核对',versions:2},{courseId:'math',name:'导数的概念与应用',type:'PPT',date:'2026-10-27',status:'制作中',versions:1},{courseId:'ai',name:'生成对抗网络的安全应用',type:'PPT',date:'2026-10-25',status:'本轮失败',versions:1},{courseId:'math',name:'函数极限 · 教学设计',type:'教案',date:'2026-10-26',status:'已生成',versions:2},{courseId:'',name:'通用课堂导入',type:'教案',date:'2026-10-12',status:'已生成',versions:1}];
const $=s=>document.querySelector(s),sum=(a,k)=>a.reduce((n,x)=>n+x[k],0),pct=(n,d)=>d?`${(n/d*100).toFixed(1)}%`:'—',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={overview:'综合概览',classroom:'课堂参与',homework:'作业与批改',survey:'问卷反馈',resources:'备课资源'};let failed=false,toastTimer;
function scope(){const course=$('#course').value,term=$('#term').value,period=$('#period').value;const from=period==='7'?'2026-10-25':period==='30'?'2026-10-02':period==='custom'?$('#from').value:'0000-01-01',to=period==='custom'?$('#to').value:'2026-10-31';const courses=COURSES.filter(c=>(course==='all'||c.id===course)&&(term==='all'||c.term===term));const ids=new Set(courses.map(c=>c.id));const filter=a=>a.filter(x=>(ids.has(x.courseId)||(x.courseId===''&&course==='all'&&term==='all'))&&x.date>=from&&x.date<=to);return {courses,sessions:filter(SESSIONS),homework:filter(HOMEWORK),surveys:filter(SURVEYS),resources:filter(RESOURCES),from,to};}
function badge(s){return `<span class="pill ${/失败|异常/.test(s)?'red':/回收|制作|核对/.test(s)?'amber':'green'}">${esc(s)}</span>`;}
const ICONS={courses:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M8 4v16M11 9h6M11 13h6"/>',classroom:'<path d="M3 3v18h18M6 15l4-5 4 3 6-8"/>',homework:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 12l2 2 4-4M9 17h6"/>',survey:'<path d="M4 3h16v14H9l-5 4V3Z M8 7h8M8 11h5"/>',resources:'<path d="M3 7h7l2-3h9v16H3V7Z M7 12h10M7 16h6"/>',warnings:'<path d="m12 3 10 18H2L12 3Z M12 9v5M12 17h.01"/>',tasks:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 9 1 1 2-2M13 9h3m-8 6 1 1 2-2M13 15h3"/>'};
function iconFor(key){return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${ICONS[key]||ICONS.courses}</svg>`;}
function panel(title,sub,body,action=''){const key=title.includes('课堂')?'classroom':title.includes('作业')?'homework':title.includes('问卷')?'survey':title.includes('备课')?'resources':title.includes('处理')?'tasks':'courses';return `<section class="panel"><div class="panel-head"><div class="panel-heading"><span class="section-icon ${key}">${iconFor(key)}</span><div><h2>${title}</h2><p class="caption">${sub}</p></div></div>${action}</div>${body}</section>`;}
function link(label,target){return `<button class="text-button" data-tab="${target}">${label} ↗</button>`;}
function stat(label,value,unit,sub,target){const percent=String(value).endsWith('%')?Number.parseFloat(value):null;return `<button class="stat metric-${target}" data-tab="${target}"><span class="stat-label">${label}<span class="mini-icon">${iconFor(target)}</span></span><div class="metric-value"><strong>${value}<em>${unit}</em></strong>${percent!==null?`<span class="metric-ring" aria-hidden="true" style="--progress:${percent}%"></span>`:''}</div><small>${sub}</small></button>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function progress(label,n,d,color='#487fe0'){return `<div class="progress-row"><div class="progress-label"><span>${label}</span><span>${n} / ${d}</span></div><div class="track"><i style="--w:${d?Math.min(100,n/d*100):0}%;--c:${color}"></i></div></div>`;}
function empty(){return `<section class="panel empty"><div>▥</div><h2>所选范围暂无活动记录</h2><p>可以更换课程或扩大日期范围。当前课程和名单仍按存量展示。</p><button data-reset>查看全部示例数据</button></section>`;}
function chart(s){if(!s.length)return '<div class="empty"><p>暂无课堂记录</p></div>';const series=[['出勤率','#6272dc',x=>x.present/x.total*100],['答题参与率','#2ca997',x=>x.answered/x.total*100],['答对率','#d6a14b',x=>x.correct/x.answered*100]];const W=620,H=190,X=i=>42+i*(560/Math.max(1,s.length-1)),Y=v=>155-v*1.3;return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="所选课堂的出勤率、答题参与率和答对率趋势">${[0,25,50,75,100].map(v=>`<line x1="42" y1="${Y(v)}" x2="608" y2="${Y(v)}"/><text x="4" y="${Y(v)+4}">${v}%</text>`).join('')}${s.length>1?`<defs><linearGradient id="attendanceFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#6475e8" stop-opacity=".17"/><stop offset="100%" stop-color="#6475e8" stop-opacity="0"/></linearGradient></defs><path d="M ${X(0)} 155 L ${s.map((x,i)=>`${X(i)} ${Y(x.present/x.total*100)}`).join(' L ')} L ${X(s.length-1)} 155 Z" fill="url(#attendanceFill)"/>`:''}${series.map(([n,c,f])=>`<polyline class="series" stroke="${c}" points="${s.map((x,i)=>`${X(i)},${Y(f(x))}`).join(' ')}"/>${s.map((x,i)=>`<circle cx="${X(i)}" cy="${Y(f(x))}" r="3" fill="${c}"><title>${x.date} ${n} ${f(x).toFixed(1)}%</title></circle>`).join('')}`).join('')}${s.filter((_,i)=>i%Math.max(1,Math.ceil(s.length/6))===0||i===s.length-1).map(x=>`<text text-anchor="middle" x="${X(s.indexOf(x))}" y="180">${x.date.slice(5)}</text>`).join('')}</svg>`;}
function trend(s){return panel('课堂参与趋势','已结束且有有效记录的签到 · 示例按当前名单统计',`<div class="legend"><span style="--c:#6272dc">出勤率</span><span style="--c:#2ca997">答题参与率</span><span style="--c:#d6a14b">答对率</span></div>${chart(s)}<div class="insight">比例按到课、作答与应到人次加权统计；进行中的课堂不计入历史趋势。</div>`,link('课堂分析','classroom'));}
function todos(d){const rows=[];d.resources.filter(r=>r.status==='本轮失败').forEach(r=>rows.push([r.name,'本轮制作失败 · 已有版本保留','red','resources']));const pending=sum(d.homework,'pending');if(pending)rows.push(['作业文件待匹配',`${pending} 份文件需要核对归属`,'amber','homework']);const collecting=d.surveys.filter(s=>s.status==='回收中').length;if(collecting)rows.push(['问卷正在回收',`${collecting} 份问卷可查看最新反馈`,'','survey']);d.resources.filter(r=>r.status==='待核对').forEach(r=>rows.push([r.name,'课件已生成 · 待逐页核对','','resources']));return rows.map(([n,s,c,t])=>`<div class="todo" role="button" tabindex="0" data-tab="${t}"><span class="todo-symbol ${c}">${c==='red'?'!':c==='amber'?'⌁':'✓'}</span><div><div class="todo-title">${n}</div><small>${s}</small></div><span class="count">↗</span></div>`).join('')||'<p class="caption">当前没有待处理事项</p>';}
function overview(d){
 const total=sum(d.sessions,'total'),present=sum(d.sessions,'present'),answered=sum(d.sessions,'answered'),correct=sum(d.sessions,'correct');
 const named=d.surveys.filter(s=>s.mode==='named'),scored=sum(d.homework,'scored'),expected=sum(d.homework,'total');
 const stats=`<div class="stats">${stat('课程 / 名单',d.courses.length,'门',`当前 · ${sum(d.courses,'students')} 课程名单人次`,'courses','▤')}${stat('出勤率',pct(present,total),'',`${d.sessions.length} 场签到 · ${present}/${total} 人次`,'classroom','◷')}${stat('答对率',pct(correct,answered),'',`有效作答 ${answered} 人次`,'classroom','⌁')}${stat('作业录分',pct(scored,expected),'',`${d.homework.length} 份作业 · ${scored}/${expected} 人次`,'homework','✓')}${stat('问卷答卷',sum(d.surveys,'count'),'份',`${d.surveys.filter(s=>s.status==='回收中').length} 份问卷回收中`,'survey','▧')}${stat('学情关注',sum(d.courses,'warn'),'人次','当前全量 · 按课程计数','warnings','⚑')}</div>`;
 if(!d.sessions.length&&!d.homework.length&&!d.surveys.length&&!d.resources.length)return stats+empty();
 const classPanel=panel('课堂参与','期间 · 有效签到记录',`<div class="inline-kpis"><span>到课 <b>${present}</b><small> / ${total} 人次</small></span><span>迟到 <b>${sum(d.sessions,'late')}</b></span><span>缺勤 <b>${total-present}</b></span><span>作答参与 <b>${pct(answered,total)}</b></span></div><div class="legend"><span style="--c:#6272dc">出勤率</span><span style="--c:#2ca997">作答参与率</span><span style="--c:#d6a14b">答对率</span></div>${chart(d.sessions)}`);
 const hwPanel=panel('作业与批改','期间 · 未录分不等于未交',`<div class="inline-kpis"><span>未录分 <b>${expected-scored}</b></span><span>明确未交 <b>${sum(d.homework,'missing')}</b></span><span>待匹配 <b>${sum(d.homework,'pending')}</b></span><span>异常 <b>${sum(d.homework,'abnormal')}</b></span></div>${d.homework.length?table(['作业','录分进度','均分',''],d.homework.map((h,i)=>[h.name,`<div class="cell-progress">${h.scored}/${h.total}<div class="track"><i style="--w:${h.scored/h.total*100}%"></i></div></div>`,h.mean,`<button class="text-button" data-homework="${i}">明细</button>`])):'<p class="caption">期间暂无作业</p>'}`);
 const surveyPanel=panel('问卷回收','期间 · 实名按发布名单，匿名仅计份数',`<div class="inline-kpis"><span>实名回收 <b>${pct(sum(named,'count'),sum(named,'target'))}</b></span><span>实名未提交 <b>${sum(named,'target')-sum(named,'count')}</b><small> 人次</small></span><span>匿名答卷 <b>${sum(d.surveys.filter(s=>s.mode==='anonymous'),'count')}</b><small> 份</small></span></div>${d.surveys.length?table(['问卷','方式','回收',''],d.surveys.map((q,i)=>[q.name,q.mode==='named'?'实名':'匿名',q.mode==='named'?`${q.count}/${q.target}`:`${q.count} 份`,`<button class="text-button" data-survey="${i}">分析</button>`])):'<p class="caption">期间暂无问卷</p>'}`);
 const coursePanel=panel('课程教学概况','当前名单 · 期间课堂与问卷',table(['课程','名单','签到','出勤率','答对率','答卷','关注人次'],d.courses.map(c=>{const x=d.sessions.filter(s=>s.courseId===c.id);return [c.name,c.students,x.length,pct(sum(x,'present'),sum(x,'total')),pct(sum(x,'correct'),sum(x,'answered')),sum(d.surveys.filter(s=>s.courseId===c.id),'count'),c.warn];})), '<button class="text-button" data-detail="warnings">关注规则 ↗</button>');
 const resourcePanel=panel('备课与模板','期间有产物的任务 · 模板为当前全局库存',`<div class="inline-kpis"><span>PPT <b>${d.resources.filter(r=>r.type==='PPT').length}</b></span><span>教案 <b>${d.resources.filter(r=>r.type==='教案').length}</b></span><button class="text-button" data-detail="templates">模板 4 PPT / 3 教案 ↗</button></div>${d.resources.slice(0,3).map((r,i)=>`<div class="resource-line"><span title="${r.name}">${r.name}</span>${badge(r.status)}<button class="text-button" data-resource="${i}">查看</button></div>`).join('')||'<p class="caption">期间暂无产物</p>'}`);
 return stats+`<div class="dense-grid"><div id="classroom" class="span8">${classPanel}</div><div id="tasks" class="span4">${panel('需要处理','优先查看异常与待确认事项',todos(d))}</div><div id="homework" class="span6">${hwPanel}</div><div id="survey" class="span6">${surveyPanel}</div><div id="courses" class="span7">${coursePanel}</div><div id="resources" class="span5">${resourcePanel}</div></div><p id="warnings" class="scope-note">统计口径：历史课堂按当前名单；迟到已包含在到课中；关注人次按当前课程全量规则统计。示例数据截至2026-10-31。</p>`;
}
function questionCharts(){return `<div class="grid equal">${panel('逐题分析 · 柱状图','示例单选题：你认为当前课堂节奏如何？',progress('比较合适',28,41)+progress('略快，希望多一些示例',9,41,'#2ca997')+progress('略慢，可以加快节奏',4,41,'#d6a14b')+'<p class="note">有效作答 41 份 · 柱形按有效作答人数统计</p>')}${panel('同题分布 · 环形图','与左侧同时展示，便于比较比例',`<div class="donut-wrap"><div class="donut" style="background:conic-gradient(#467fe6 0 68.3%,#75bba8 68.3% 90.2%,#e0b563 90.2%)"><div><strong>41</strong><small>有效作答</small></div></div><div class="legend" style="flex-direction:column"><span style="--c:#6272dc">比较合适 · 68.3%</span><span style="--c:#2ca997">略快 · 22.0%</span><span style="--c:#d6a14b">略慢 · 9.8%</span></div></div>`)}</div>`;}
function render(){const d=scope();$('#customDates').hidden=$('#period').value!=='custom';const invalid=!d.from||!d.to||d.from>d.to;$('#dateError').hidden=!invalid;$('#dateError').textContent='请选择有效日期范围，开始日期不能晚于结束日期。';if(invalid)return;const content=overview(d);$('#content').innerHTML=(failed?'<div class="error" role="alert">课堂趋势暂时加载失败。当前保留上次成功的示例数据，其余分区可继续查看。<button data-retry>重试</button></div>':'')+content;$('#syncTime').textContent=`示例截至 2026-10-31 · 刷新于 ${new Date().toLocaleTimeString('zh-CN',{hour12:false})}`;}
function notify(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3000);}
function detail(title,body){$('#detailTitle').textContent=title;$('#detailBody').innerHTML=body;$('#detail').showModal();$('#closeDetail').focus();}
document.addEventListener('click',e=>{const t=e.target.closest('[data-tab],[data-reset],[data-session],[data-homework],[data-survey],[data-resource],[data-detail],[data-retry]');if(!t)return;const d=scope();if(t.dataset.tab){const target=$('#'+t.dataset.tab);if(target?.scrollIntoView)target.scrollIntoView({behavior:'smooth',block:'start'});}if(t.hasAttribute('data-reset')){$('#course').value='all';$('#term').value='all';$('#period').value='30';render();}if(t.hasAttribute('data-retry')){failed=false;render();notify('示例数据已重新加载');}if(t.hasAttribute('data-session')){const s=d.sessions[+t.dataset.session];detail(`${s.date} · 课堂记录`,table(['指标','人数 / 人次'],[['应到',s.total],['到课（含迟到）',s.present],['迟到',s.late],['缺勤',s.total-s.present],['有效作答',s.answered],['答对',s.correct]])+'<p class="note">课堂名单未做历史快照，本原型按当前名单展示。正式实现将跳转原课堂详情。</p>');}if(t.hasAttribute('data-homework')){const h=d.homework[+t.dataset.homework];detail(h.name,table(['项目','数量'],[['已录分',h.scored],['未录分（含明确未交）',h.total-h.scored],['明确未交',h.missing],['已匹配文件学生',h.matched],['待匹配文件',h.pending],['异常结果',h.abnormal]])+'<p class="note">这里只展示示例明细，不会发起批改或修改学生成绩。</p>');}if(t.hasAttribute('data-survey')){const s=d.surveys[+t.dataset.survey];detail(s.name,`<p>${s.mode==='anonymous'?'匿名问卷只统计答卷份数，不识别未提交学生。':`发布名单快照 ${s.target} 人，已回收 ${s.count} 份，未提交 ${s.target-s.count} 人。`}</p><div style="height:20px"></div>${s.mode==='named'?questionCharts():'<p class="note">匿名问卷不识别未提交学生。原型题目分布示例请见问卷页下方，正式版将进入该问卷结果。</p>'}`);}if(t.hasAttribute('data-resource')){const r=d.resources[+t.dataset.resource];detail(r.name,`${badge(r.status)}<p style="margin-top:18px">${r.status==='本轮失败'?'本轮制作超时，要求与历史版本均已保留。可返回任务核查后重试。':'示例产物已保留，可在正式业务模块继续核对。'}</p>${table(['已有产物','状态'],Array.from({length:r.versions},(_,i)=>[`版本 ${i+1}`,badge('历史保留')]))}<p class="note">此处不调用WorkBuddy、不执行重试或导出。</p>`);}if(t.dataset.detail==='warnings')detail('当前关注规则','<p>连续缺勤、近期答对率偏低、作业记录异常等规则触发后进入关注名单。</p><p class="note">示例为课程关注人次，不能据此推断学生能力。现有规则中缺成绩与未交需进一步区分；正式新看板不会把缺成绩直接写成已核实未交。</p>');if(t.dataset.detail==='templates')detail('模板库存',table(['模板','类型','布局/来源'],[['简洁蓝 · 课堂通用','PPT','5种布局'],['人工智能安全','PPT','8种布局'],['浅色图文','PPT','6种布局'],['课程汇报','PPT','3种布局'],['标准教学设计','教案','内置'],['实践课设计','教案','上传'],['专题授课','教案','上传']])+'<p class="note">所有模板均为虚构示例，全局库存不受活动日期筛选影响。</p>');});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.todo[role="button"]')){e.preventDefault();e.target.click();}});
['course','term','period','from','to'].forEach(id=>$('#'+id).addEventListener('change',render));window.addEventListener('hashchange',render);$('#refresh').onclick=()=>{failed=false;render();notify('示例数据已刷新');};$('#simulateError').onclick=()=>{failed=true;render();};$('#closeDetail').onclick=$('#doneDetail').onclick=()=>$('#detail').close();render();
